class my_sign_class(torch.autograd.Function):

    @staticmethod
    def forward(ctx, input):
        ctx.input = input
        return (torch.sign(input) + 1) / 2 

    @staticmethod
    def backward(ctx, grad_output):
        scalar = 5.
        input = ctx.input
        temp = torch.sigmoid(scalar * input)
        # return grad_output*1
        return grad_output * temp * (1 - temp) * scalar

This section exactly implements the BPDA-sigmoid for sign
